import skill from '../../skills/fluentui-svelte/SKILL.md?raw';
// Generated by scripts/gen-llms.js (`pnpm urls`): META without the icon components.
import componentsIndex from '#site/utils/llms-index.js';
import { SITE_NAME, SITE_URL } from '#site/constants.js';

/**
 * The documents published for AI agents. `/docs/llms.md` is the body of the agent skill, so the
 * skill, the site and the package always say the same thing; every component has its own
 * `docs/llms.md`, served at `/docs/components/<slug>.md`.
 */

const componentFiles = import.meta.glob<string>('/src/lib/components/*/docs/llms.md', {
	query: '?raw',
	import: 'default'
});

/** The components listed for agents: the ones the docs navigation shows in production. */
export const llmsComponents = componentsIndex.filter((meta) => meta.status !== 'Empty');

/** The skill without its YAML front matter. */
export const globalGuide = skill.replace(/^---\r?\n[\s\S]*?\r?\n---\r?\n+/, '');

/** Absolute URL of the Markdown version of a component page. */
export const componentMarkdownUrl = (slug: string) => `${SITE_URL}/docs/components/${slug}.md`;

/** The `llms.md` of a component, or `null` when there is no such component. */
export async function componentMarkdown(slug: string): Promise<string | null> {
	const load = componentFiles[`/src/lib/components/${slug}/docs/llms.md`];
	return load ? await load() : null;
}

/** `/llms.txt`, following https://llmstxt.org. */
export function llmsIndex(): string {
	const components = llmsComponents.map(
		(meta) => `- [${meta.title}](${componentMarkdownUrl(meta.slug)}): ${meta.description}`
	);

	return [
		`# ${SITE_NAME}`,
		'',
		'> Fluent UI 2 components for Svelte 5, published on npm as `fluentui-svelte`. Every component is exported from the package root, needs `fluentui-svelte/theme.css` and works best inside the `FluentUISvelte` provider.',
		'',
		'Read the global guide before writing code with the library: it covers setup, the conventions every component shares and the mistakes agents make most often. Each component guide matches the latest release; the installed version ships its own copy in `node_modules/fluentui-svelte/dist/components/<name>/docs/llms.md`.',
		'',
		'## Docs',
		'',
		`- [Global guide](${SITE_URL}/docs/llms.md): setup, shared conventions, pitfalls and the index of components.`,
		`- [Types reference](${SITE_URL}/docs/types): the shared types named in the prop tables.`,
		'',
		'## Components',
		'',
		...components,
		'',
		'## Optional',
		'',
		`- [Full documentation](${SITE_URL}/llms-full.txt): the global guide and every component guide in one file.`,
		''
	].join('\n');
}

/** `/llms-full.txt`: the global guide followed by every component guide. */
export async function llmsFull(): Promise<string> {
	const guides = await Promise.all(llmsComponents.map((meta) => componentMarkdown(meta.slug)));
	const sections = [globalGuide, ...guides.filter((guide): guide is string => guide !== null)];
	return sections.map((section) => section.trim()).join('\n\n---\n\n') + '\n';
}

/** A plain-text response for an agent-facing document. */
export function textResponse(body: string, type: 'text/markdown' | 'text/plain') {
	return new Response(body, {
		headers: {
			'Content-Type': `${type}; charset=utf-8`,
			'X-Robots-Tag': 'noindex'
		}
	});
}
